#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""缓存指标 —— **纯逻辑,零 IO**。规格 §17.2 + 附录 A-8。

## 这个文件要防的那一件事

> **命中率高本身不代表合格**(规格 §1 的原话)。

而比「命中率不代表合格」更具体的是:**这些数字有好几种算法都「看起来合理」,
而其中大部分会把假收益算出来**。规格 §17.2 把分母逐条钉死了,附录 A-8 列了
三种错法:「把无调用当未命中、只展示成功样本、用总均值掩盖关键错用」。

## 四条硬规矩

### ① 分母为 0 → **「不适用」**,不是 0%

一个没有任何适用请求的应用,命中率是**不适用**,不是 0%。
> 「这个策略一次都没命中」和「这个策略一次都没用上」,
> **在 0% 上长得一模一样** —— 而前者要去查,后者不用。

实测过同形状的一次(CLAUDE.md §8):客户表一空,RFM 五条性质全绿,
而「什么都没验」和「验过了没问题」在输出上长得一样。

### ② 未知 → **`None`**,不是 0

供应商没给缓存用量字段时,那次调用的缓存读是**未知**,不是 0。
规格 §7:「无供应商字段显示「未知」,**不能显示 0% 命中**」。
所以这里每个指标都带一个 `未知多少` —— 而且**未知不进分子也不进分母**,
另报覆盖率。

### ③ 答案命中 → **本次没有生成调用**,但那不等于「免费」

规格 §15.2:「可确认没有模型调用时本次生成费用为 0,
**但缓存查询和存储的总费用可仍未知**」。
而附录 A-6 点名的错法是「**复用旧费用形成假节省**」——
所以答案命中那一次**不复制来源那次的账目**。

### ④ 省了多少钱 **不能从「调用少了」推出来**

审阅原话:「**不能依据工具数下降或 Token 数下降直接宣称成本下降**;
使用同一任务、同等缓存条件核算完整调用费用」。
所以 `净节省估算()` 要求显式给出**对照是怎么来的**
(实测对比 / 按固定用量的反事实估算),而且**未知项单列、不并进节省**。

## 它不做什么

- 不读库、不读 Trace。调用方把**已经分好类的计数**递进来。
- 不做抽样。A-8 要求「抽样规则冻结」,那是调用方的事。
- 不判一次复用对不对。
"""

不适用 = "不适用"      # 分母为 0
未知 = None            # 字段缺失


class 算不了(Exception):
    """输入本身讲不通 —— **当场抛,不返回一个看起来合理的数**。"""


def _比(分子, 分母, *, 什么的分母):
    """算一个比率。**分母为 0 → 「不适用」,不是 0**。"""
    if 分子 is None or 分母 is None:
        return 未知
    if 分子 < 0 or 分母 < 0:
        raise 算不了(f"计数不能是负的(分子 {分子} / 分母 {分母})")
    if 分子 > 分母:
        # ⚠️ **分子大于分母要抛,不许截到 100%。**
        # 截了的话,「事件重复计数」这种 bug 会显示成一个漂亮的 100%,
        # 而那正是 A-8 要防的「重复事件」夹具。
        raise 算不了(
            f"分子({分子})比分母({分母})大 —— {什么的分母}。"
            f"**不截到 100%**:截了的话「事件被重复计数」会显示成一个漂亮的数")
    if 分母 == 0:
        return 不适用
    return 分子 / 分母


def 答案命中率(*, 返回了缓存答案的请求数, 真的尝试过查缓存的请求数):
    """规格 §17.2:**实际返回缓存答案 ÷ 实际尝试答案查询**。

    ⚠️ 分母**不是**「全部请求」。规格把那个另算成「答案复用覆盖率」——
    两者混在一起的后果:一个「只对 3% 请求开了缓存、而那 3% 全命中」的策略,
    和一个「对全部请求开了、命中 3%」的策略,**在同一个百分比上长得一模一样**。
    """
    return _比(返回了缓存答案的请求数, 真的尝试过查缓存的请求数,
              什么的分母="分母是「真的尝试过查缓存」的请求数")


def 答案复用覆盖率(*, 返回了缓存答案的请求数, 全部请求数):
    """规格 §17.2:返回缓存答案 ÷ **全部**对应应用请求数。和命中率分开报。"""
    return _比(返回了缓存答案的请求数, 全部请求数,
              什么的分母="分母是该应用的全部请求数")


def 提示词命中调用率(*, 确认缓存读大于0的调用数, 缓存读字段已知的调用数,
               总生成调用数):
    """规格 §17.2:确认缓存读 > 0 的调用 ÷ **缓存读字段已知**的调用。

    ⚠️ 分母是「字段已知的」,不是「全部调用」——
    供应商没给字段的那些是**未知**,既不算命中也不算未命中。
    另报 `可观测覆盖率`(规格明写「另报可观测覆盖率」)。

    ⚠️ 附录 A-8 点名的错法:「**把无调用当未命中**」。
    答案缓存命中那一次**根本没有生成调用** —— 它不该进这个分母。
    """
    if None in (确认缓存读大于0的调用数, 缓存读字段已知的调用数, 总生成调用数):
        raise 算不了("三个计数都要给(未知要显式传 0 并在覆盖率里体现),"
                   "**不许省一个让它当 0** —— 省掉的那个会让分母变小、命中率变高")
    return {
        "命中率": _比(确认缓存读大于0的调用数, 缓存读字段已知的调用数,
                   什么的分母="分母是**缓存读字段已知**的生成调用数"),
        "可观测覆盖率": _比(缓存读字段已知的调用数, 总生成调用数,
                      什么的分母="分母是全部生成调用数"),
        "未知的调用数": 总生成调用数 - 缓存读字段已知的调用数,
        "怎么读": ("命中率的分母**只含供应商给了字段的那些** —— "
                 "没给字段的是「未知」,不是「未命中」。"
                 "覆盖率低的时候,命中率这个数的代表性就低"),
    }


def 抽检错误复用率(*, 判为不适用的交付数, 完成独立抽检的交付数, 抽样怎么来的):
    """规格 §17.2:被判不适用 ÷ **已完成独立抽检**的缓存交付数。

    ⚠️ 规格 §7 明写:「抽检错误率旁**显示抽检量**,
    **不能代表全部请求的真实错误率**」。
    所以这里**强制要求**说明抽样方法 —— 不给就抛。

    > 一个抽了 5 条、零错的结论,和一个抽了 500 条、零错的结论,
    > **在那个 0% 上长得一模一样**。
    """
    if not (抽样怎么来的 or "").strip():
        raise 算不了("没说抽样是怎么来的 —— **抽检率不带抽样方法等于没有意义**"
                   "(规格 §17.2:附抽样方法与区间)")
    率 = _比(判为不适用的交付数, 完成独立抽检的交付数,
           什么的分母="分母是**已完成独立抽检**的缓存交付数")
    return {
        "错误复用率": 率,
        "抽检了多少": 完成独立抽检的交付数,
        "抽样怎么来的": 抽样怎么来的,
        "怎么读": ("⚠️ **这不是全部请求的真实错误率。** "
                 + (f"只抽了 {完成独立抽检的交付数} 条,"
                    f"**少量抽检零错不能宣称总体零错**"
                    if (完成独立抽检的交付数 or 0) < 30 else
                    f"抽了 {完成独立抽检的交付数} 条")),
    }


def 已知生成费用(*, 计费桶们, 单价们):
    """规格 §17.2:`Σ(每个互斥计费桶的用量 × 该桶当时的单价)`。

    返回 `(金额或 None, 没有单价的桶们)`。
    **任一桶缺单价 → 金额是 `None`(未知),不是「少算了那一桶的部分和」**。

    ⚠️ 这一条是和 `knowledge/usage.py` 同一个口径 ——
    那边的做法是「token 已知、金额未知」,**不编单价也不写 0**。
    这里不另立一套:缺价就是未知。
    > 一个少算了一桶的总额,和一个算全了的总额,**在那个数字上长得一模一样**。
    """
    缺价 = sorted(k for k in 计费桶们 if 单价们.get(k) is None)
    if 缺价:
        return 未知, 缺价
    return sum(n * 单价们[k] for k, n in 计费桶们.items()), []


def 净节省估算(*, 基线费用, 当前已知费用, 还没纳入的缓存成本, 对照是怎么来的):
    """规格 §17.2:`基线估算 − 当前实际已知 − 尚未纳入的缓存相关成本`;**未知项单列**。

    ⚠️ **`对照是怎么来的` 是必填,而且只收两种值**:
    `"实测对比"` 或 `"反事实估算"`(规格原话:「对照收益需明确是实测对比
    还是按固定用量的反事实估算」)。

    ⚠️ 审阅点名:「**不能依据工具数下降或 Token 数下降直接宣称成本下降**」。
    所以这个函数**不接受「调用少了多少」这类输入** —— 它只接受钱。

    ⚠️ 任一项未知 → 整个净节省是**未知**,并把未知的那几项列出来。
    > 一个把未知项当 0 算出来的「省了 71%」,和一个真的省了 71% 的,
    > **在那个百分比上长得一模一样** —— 这个仓库 2026-10-03 栽过一次
    > (基线臂在写缓存、对照臂吃热缓存,真数是 12%)。
    """
    if 对照是怎么来的 not in ("实测对比", "反事实估算"):
        raise 算不了("`对照是怎么来的` 只收「实测对比」或「反事实估算」—— "
                   "规格要求明确这一点,因为两者的可信度完全不同:"
                   "反事实估算是**按固定用量算出来的**,不是真跑过的")
    未知项 = [名 for 名, v in (("基线费用", 基线费用),
                            ("当前已知费用", 当前已知费用),
                            ("还没纳入的缓存成本", 还没纳入的缓存成本))
            if v is None]
    if 未知项:
        return {
            "净节省": 未知, "未知项": 未知项, "对照是怎么来的": 对照是怎么来的,
            "怎么读": (f"**算不出净节省** —— 这几项是未知的:{未知项}。"
                     f"把未知当 0 算出来的节省,和真的节省,"
                     f"**在那个数字上长得一模一样**"),
        }
    净 = 基线费用 - 当前已知费用 - 还没纳入的缓存成本
    return {
        "净节省": 净, "未知项": [], "对照是怎么来的": 对照是怎么来的,
        "怎么读": ("**这是" + ("实测对比" if 对照是怎么来的 == "实测对比"
                           else "按固定用量的反事实估算,不是真跑出来的")
                 + "。** 而且对照的生成长度或质量变了的话,"
                   "差额不可直接归因于缓存(附录 A-6 的局限栏)"),
    }


def 一次答案命中的账(*, 来源那次的费用, 本次缓存查询费用=未知,
             本次存储费用=未知):
    """答案命中那一次的账 —— **本次生成费用是 0,而总费用可能仍未知**。

    规格 §15.2:「可确认没有模型调用时本次生成费用为 0,
    **但缓存查询和存储的总费用可仍未知**。
    历史答案长度**不计入**本次新生成 Token」。

    ⚠️ 附录 A-6 点名的错法:「**复用旧费用形成假节省**」。
    所以 `来源那次的费用` 在这里**只用来显示来路**,不参与本次总额。
    """
    未知项 = [名 for 名, v in (("缓存查询费用", 本次缓存查询费用),
                            ("存储费用", 本次存储费用)) if v is None]
    return {
        "本次生成费用": 0.0,
        "本次总费用": (未知 if 未知项
                   else (本次缓存查询费用 or 0) + (本次存储费用 or 0)),
        "未知项": 未知项,
        "来源那次花了多少": 来源那次的费用,
        "⚠️": ("**来源那次的费用只是来路,不进本次总额** —— "
               "把它复制过来就是「复用旧费用形成假节省」(附录 A-6)。"
               "而本次生成费用是 0 **不等于本次免费**:"
               "缓存查询和存储仍然要钱,"
               + (f"而这几项现在是未知的:{未知项}" if 未知项 else "这两项已知")),
    }
